import java.util.*;
import java.io.*;

public class Main {
    static List<long[]> commonFreeTime(List<long[][]> schedules) {
        // Write your solution here
        // Return a list of {a, b} windows sorted by a
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int p = (int) in.nval;
        List<long[][]> schedules = new ArrayList<>();
        for (int i = 0; i < p; i++) {
            in.nextToken();
            int k = (int) in.nval;
            long[][] person = new long[k][2];
            for (int j = 0; j < k; j++) {
                in.nextToken();
                person[j][0] = (long) in.nval;
                in.nextToken();
                person[j][1] = (long) in.nval;
            }
            schedules.add(person);
        }
        List<long[]> res = commonFreeTime(schedules);
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append('\n');
        for (long[] w : res) sb.append(w[0]).append(' ').append(w[1]).append('\n');
        System.out.print(sb);
    }
}
